import assert from "node:assert/strict";
import test from "node:test";
import {
  releaseAssets,
  syncCnbRelease,
  triggerReleaseSync,
  validateReleaseTag,
} from "./sync-cnb-release.mjs";

const response = (status, body = "") => ({
  ok: status >= 200 && status < 300,
  status,
  text: async () => body,
});

test("uses the release filenames generated by electron-builder", () => {
  assert.deepEqual(releaseAssets("v0.0.7"), [
    "larify-0.0.7-setup.exe",
    "larify-0.0.7-setup.exe.blockmap",
    "latest.yml",
  ]);
  assert.deepEqual(releaseAssets("v0.0.7-beta.1"), [
    "larify-0.0.7-beta.1-setup.exe",
    "larify-0.0.7-beta.1-setup.exe.blockmap",
    "beta.yml",
  ]);
});

test("accepts stable and prerelease tags and rejects unsafe tags", () => {
  assert.doesNotThrow(() => validateReleaseTag("v0.0.7"));
  assert.doesNotThrow(() => validateReleaseTag("v0.0.7-beta.1"));
  assert.throws(() => validateReleaseTag("v0.0.7;rm"), /Invalid release tag/);
});

test("does not trigger CNB when the release is already complete", async () => {
  const calls = [];
  const request = async (url, options = {}) => {
    calls.push({ url, options });
    if (options.method === "POST") throw new Error("unexpected trigger");
    return response(200, "version: 0.0.7");
  };

  const result = await syncCnbRelease({
    tag: "v0.0.7",
    token: "secret",
    request,
  });

  assert.equal(result, "already-complete");
  assert.equal(
    calls.filter(({ options }) => options.method === "POST").length,
    0,
  );
});

test("triggers the expected CNB build event with the release tag", async () => {
  let call;
  await triggerReleaseSync("v0.0.7", "secret", async (url, options) => {
    call = { url, options };
    return response(200);
  });

  assert.equal(
    call.url,
    "https://api.cnb.cool/larify-ai/larify-desktop/-/build/start",
  );
  assert.equal(call.options.method, "POST");
  assert.equal(call.options.headers.Authorization, "secret");
  assert.equal(call.options.headers["Content-Type"], "application/json");
  assert.deepEqual(JSON.parse(call.options.body), {
    event: "api_trigger_release_sync",
    env: { RELEASE_TAG: "v0.0.7" },
  });
});

test("fails immediately when CNB rejects the build trigger", async () => {
  await assert.rejects(
    triggerReleaseSync("v0.0.7", "secret", async () => response(401)),
    /HTTP 401/,
  );
});

test("retries an incomplete existing release and waits for all assets", async () => {
  let triggered = false;
  let checksAfterTrigger = 0;
  const request = async (url, options = {}) => {
    if (options.method === "POST") {
      triggered = true;
      return response(200);
    }
    if (!triggered) return response(404);
    if (options.method === "HEAD" && url.endsWith("setup.exe"))
      checksAfterTrigger += 1;
    if (checksAfterTrigger < 2) return response(404);
    return response(200, "version: 0.0.7");
  };

  const result = await syncCnbRelease({
    tag: "v0.0.7",
    token: "secret",
    request,
    wait: async () => {},
    attempts: 3,
  });

  assert.equal(result, "published");
  assert.equal(triggered, true);
});

test("fails instead of reporting success when CNB remains incomplete", async () => {
  const request = async (_url, options = {}) =>
    options.method === "POST" ? response(200) : response(404);

  await assert.rejects(
    syncCnbRelease({
      tag: "v0.0.7",
      token: "secret",
      request,
      wait: async () => {},
      attempts: 2,
    }),
    /incomplete after 2 checks/,
  );
});

test("retries transient errors while checking CNB assets", async () => {
  let triggered = false;
  let failedOnce = false;
  const request = async (_url, options = {}) => {
    if (options.method === "POST") {
      triggered = true;
      return response(200);
    }
    if (!triggered) return response(404);
    if (!failedOnce) {
      failedOnce = true;
      throw new Error("temporary network error");
    }
    return response(200, "version: 0.0.7");
  };

  assert.equal(
    await syncCnbRelease({
      tag: "v0.0.7",
      token: "secret",
      request,
      wait: async () => {},
      attempts: 2,
    }),
    "published",
  );
});
